// The starting ("usulan awal") curriculum for Kids Swim: six skills, Level 1-3
// for the four strokes, indicator rubrics, tests, targets and pass rules.
//
// This file is the SOURCE for the seed migration (0049, generated by
// scripts/gen-curriculum-seed.ts and kept in sync by a test). After seeding,
// the database is the source of truth and admin edits it in /admin/penilaian;
// nothing in the app reads this file at runtime. Every rubric text, target
// distance and pass threshold below is a proposal for the SLR teaching team
// to validate -- they are internal SLR targets, not an external standard.

export type SkillSlug = "dasar" | "water_safety" | "bebas" | "dada" | "punggung" | "kupu";
export type SkillKind = "foundation" | "safety" | "stroke";

export type SeedSkill = {
  slug: SkillSlug;
  // canonical name; also used to match an existing group by normalized name
  name: string;
  kind: SkillKind;
  hasLevels: boolean;
  sortOrder: number;
};

export type SeedIndicator = {
  skill: SkillSlug;
  level: 1 | 2 | 3 | null;
  slug: string;
  label: string;
  description: string;
  rubric: string;
  sortOrder: number;
};

export type SeedTestType = {
  skill: SkillSlug;
  code: string;
  label: string;
  measure: "distance_m" | "duration_s" | "checklist";
  levelSpecific: boolean;
  steps?: string[];
  sortOrder: number;
};

export type SeedTarget = {
  testCode: string;
  level: 1 | 2 | 3;
  value: number;
};

export type SeedRule = {
  skill: SkillSlug;
  level: 1 | 2 | 3 | null;
  masteryMinScore: number;
  minEvidenceSessions: number;
  requiresTest: boolean;
};

export const LEVEL_NAMES: Record<1 | 2 | 3, string> = {
  1: "Dasar",
  2: "Pengembangan",
  3: "Penguasaan",
};

