// ---------- Strokes: five/six aspects x three levels ----------
// star5 per level; the description is shared across levels.
type Aspect = {
  slug: string;
  label: string;
  description: string;
  star5: [string, string, string];
};

function strokeIndicators(skill: SkillSlug, aspects: Aspect[]): SeedIndicator[] {
  const out: SeedIndicator[] = [];
  for (const level of [1, 2, 3] as const) {
    aspects.forEach((a, i) => {
      out.push(
        indicator(
          skill,
          level,
          `l${level}_${a.slug}`,
          a.label,
          a.description,
          a.star5[level - 1],
          undefined,
          level * 10 + i + 1
        )
      );
    });
  }
  return out;
}

